 similar_images:(s.images||[]).map(i=>({image_id:i.image_id,patient_id:i.patient_id,source_image_reference:i.source_image_reference,split:i.split,modality:i.modality,rank:i.rank,similarity:i.similarity,association_level:i.association_level,association_warning:i.association_warning})),
